package source

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"os"
	"path/filepath"
	"testing"

	"github.com/iamletenkov/cream/internal/cerr"
)

// tarEntry is one header of a test archive; typ defaults to a regular file.
type tarEntry struct {
	name string
	typ  byte
	body string
	link string
	mode int64
	pax  map[string]string // PAX records, for tar.TypeXGlobalHeader
}

// makeTarGz builds a tar.gz in memory: hostile archives are generated by the
// tests, never committed as binaries.
func makeTarGz(t *testing.T, entries []tarEntry) []byte {
	t.Helper()
	var buf bytes.Buffer
	zw := gzip.NewWriter(&buf)
	tw := tar.NewWriter(zw)
	for _, e := range entries {
		typ := e.typ
		if typ == 0 {
			typ = tar.TypeReg
		}
		mode := e.mode
		if mode == 0 {
			mode = 0o644
			if typ == tar.TypeDir {
				mode = 0o755
			}
		}
		h := &tar.Header{Name: e.name, Typeflag: typ, Linkname: e.link, Mode: mode, Format: tar.FormatPAX}
		if typ == tar.TypeXGlobalHeader {
			h = &tar.Header{Name: e.name, Typeflag: typ, PAXRecords: e.pax}
		}
		if typ == tar.TypeReg {
			h.Size = int64(len(e.body))
		}
		if err := tw.WriteHeader(h); err != nil {
			t.Fatalf("tar header %s: %v", e.name, err)
		}
		if typ == tar.TypeReg {
			if _, err := tw.Write([]byte(e.body)); err != nil {
				t.Fatalf("tar body %s: %v", e.name, err)
			}
		}
	}
	if err := tw.Close(); err != nil {
		t.Fatal(err)
	}
	if err := zw.Close(); err != nil {
		t.Fatal(err)
	}
	return buf.Bytes()
}

func sha256Hex(b []byte) string {
	s := sha256.Sum256(b)
	return hex.EncodeToString(s[:])
}

// writeTree creates files (path → content; a trailing "/" makes a directory).
func writeTree(t *testing.T, root string, files map[string]string) {
	t.Helper()
	for rel, body := range files {
		p := filepath.Join(root, rel)
		if rel[len(rel)-1] == '/' {
			if err := os.MkdirAll(p, 0o755); err != nil {
				t.Fatal(err)
			}
			continue
		}
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, []byte(body), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

func readFile(t *testing.T, p string) string {
	t.Helper()
	b, err := os.ReadFile(p)
	if err != nil {
		t.Fatal(err)
	}
	return string(b)
}

// wantCerr checks the exit code and, if code != "", the error.code of err.
func wantCerr(t *testing.T, err error, exit int, code string) {
	t.Helper()
	if err == nil {
		t.Fatalf("ошибки нет, ждали %d %s", exit, code)
	}
	var ce *cerr.Error
	if !errors.As(err, &ce) {
		t.Fatalf("ошибка %v не *cerr.Error", err)
	}
	if got := cerr.ExitCode(err); got != exit {
		t.Errorf("код %d (%s: %v), ждали %d", got, cerr.CodeOf(err), err, exit)
	}
	if code != "" && cerr.CodeOf(err) != code {
		t.Errorf("error.code %q (%v), ждали %q", cerr.CodeOf(err), err, code)
	}
}
